{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Lopinavir, the closest analogue (Morgan 0.3119) sharing the hydroxyethylene dipeptide isostere and valine-derived urea cap, has low oral bioavailability in humans due to extensive CYP3A4 first-pass metabolism and P-glycoprotein efflux; this directly supports a low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Atazanavir has an absolute oral bioavailability of 68% in humans despite high molecular weight and polar surface area, showing that some HIV protease inhibitors can be well absorbed; however, its aza-peptide scaffold is less structurally similar to the query, so this contradictory evidence carries lower weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "Darunavir has an oral bioavailability of 37% when given alone, which is above the 20% threshold, but it is described as low and requires ritonavir boosting; its sulfonamide-hydroxyethylamine core is less transferable to the query's lopinavir-like scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogue, lopinavir, shares the key hydroxyethylene core and valine-derived urea cap with the query and has low/poor human oral bioavailability due to CYP3A4 metabolism and P-gp efflux. The query's high molecular weight, high PSA, and poor solubility prior reinforce low absorption. High-F HIV protease inhibitors such as atazanavir and darunavir are less structurally similar and do not override the lopinavir anchor. Prediction: low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query or an exact scaffold match.",
    "Lopinavir records are qualitative ('low/poor') rather than numeric absolute F values, so threshold-specific comparison is indirect.",
    "Morgan similarities are all below 0.32, limiting transferability of any single analogue.",
    "Potential formulation, prodrug, or boosting effects that could raise F are not captured in the available evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

